const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const afg = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017')
      .filter(ee.Filter.eq('country_na', 'Afghanistan'))
      .geometry();

    const periods = [
      { label: '2017-02', start: '2017-02-01', end: '2017-03-01' },
      { label: '2018-02', start: '2018-02-01', end: '2018-03-01' }
    ];

    const primaryId = 'MODIS/061/MOD11A2'; // Terra
    const fallbackId = 'MODIS/061/MYD11A2'; // Aqua

    // Helpers
    const getInfoAsync = (obj) => new Promise((resolve, reject) => obj.getInfo(resolve, reject));

    function maskAndScale(img) {
      const qc = img.select('QC_Day');
      const good = qc.bitwiseAnd(3).eq(0); // bits 0-1 == 00 => good quality
      const lstC = img.select('LST_Day_1km')
        .updateMask(good)
        .multiply(0.02) // scale to Kelvin
        .subtract(273.15) // to Celsius
        .rename('LSTc');
      return lstC.copyProperties(img, img.propertyNames());
    }

    async function getPeriodStats(period) {
      // Try primary
      let col = ee.ImageCollection(primaryId)
        .filterDate(period.start, period.end)
        .filterBounds(afg);
      let size = await getInfoAsync(col.size());
      let usedId = primaryId;

      // Fallback if empty
      if (size === 0) {
        col = ee.ImageCollection(fallbackId)
          .filterDate(period.start, period.end)
          .filterBounds(afg);
        size = await getInfoAsync(col.size());
        usedId = fallbackId;
      }
      if (size === 0) {
        return { empty: true, label: period.label, usedId: null, size: 0 };
      }

      const colMasked = col.map(maskAndScale);
      const meanImg = colMasked.mean().clip(afg);

      // Valid pixel count after masking
      const validCount = await getInfoAsync(
        meanImg.reduceRegion({
          reducer: ee.Reducer.count(),
          geometry: afg,
          scale: 3000,
          maxPixels: 1e9
        }).get('LSTc')
      );

      // Total possible pixels at this scale
      const totalCount = await getInfoAsync(
        ee.Image.constant(1).rename('LSTc').reduceRegion({
          reducer: ee.Reducer.count(),
          geometry: afg,
          scale: 3000,
          maxPixels: 1e9
        }).get('LSTc')
      );

      // Mean temperature
      const meanVal = await getInfoAsync(
        meanImg.reduceRegion({
          reducer: ee.Reducer.mean(),
          geometry: afg,
          scale: 3000,
          maxPixels: 1e9
        }).get('LSTc')
      );

      return {
        empty: false,
        label: period.label,
        usedId,
        size,
        validCount: validCount || 0,
        totalCount: totalCount || 0,
        meanC: meanVal
      };
    }

    const s1 = await getPeriodStats(periods[0]);
    const s2 = await getPeriodStats(periods[1]);

    // 2. Data Availability Checks
    if (s1.empty || s2.empty) {
      console.log(`${periods[0].label} Images: ${s1.size || 0} (${s1.usedId || 'None'})`);
      console.log(`${periods[1].label} Images: ${s2.size || 0} (${s2.usedId || 'None'})`);
      console.log('One or both months have no images in primary/fallback.');
      console.log('C1: Empty Collection (No images found in date/location for one or both comparison points).');
      return;
    }

    // 3. Processing checks: valid pixels
    const pct1 = s1.totalCount > 0 ? (100 * s1.validCount / s1.totalCount) : 0;
    const pct2 = s2.totalCount > 0 ? (100 * s2.validCount / s2.totalCount) : 0;

    console.log(`${s1.label} Source: ${s1.usedId.split('/').slice(-1)[0]} Images: ${s1.size}`);
    console.log(`${s1.label} Valid px: ${s1.validCount} / ${s1.totalCount} (${pct1.toFixed(1)}%)`);
    console.log(`${s1.label} Mean LST Day (°C): ${s1.meanC !== null ? s1.meanC.toFixed(2) : 'null'}`);

    console.log(`${s2.label} Source: ${s2.usedId.split('/').slice(-1)[0]} Images: ${s2.size}`);
    console.log(`${s2.label} Valid px: ${s2.validCount} / ${s2.totalCount} (${pct2.toFixed(1)}%)`);
    console.log(`${s2.label} Mean LST Day (°C): ${s2.meanC !== null ? s2.meanC.toFixed(2) : 'null'}`);

    if (s1.validCount === 0 || s2.validCount === 0) {
      console.log('C2: No Valid Pixels (Images exist, but after cloud masking/processing, 0 pixels remain).');
      return;
    }

    // 4. Validation & Final Answer
    function invalid(val) {
      return val === null || !isFinite(val) || val < -80 || val > 70;
    }
    if (invalid(s1.meanC) || invalid(s2.meanC)) {
      console.log('C3: Calculation Failure (Result is None/NaN or outside plausible range).');
      return;
    }

    const diff = s2.meanC - s1.meanC;
    console.log(`Delta (2018-02 minus 2017-02) (°C): ${diff.toFixed(2)}`);

    if (diff > 0) {
      console.log('A: Yes');
    } else {
      console.log('B: No');
    }
  } catch (err) {
    console.log(`Error: ${err && err.message ? err.message : err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
